from __future__ import annotations

import argparse
import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from typing import Any
from urllib.parse import urlsplit

from .errors import NotFoundError, ValidationError, VariantRailError
from .service import VariantRail


class RawBody:
    """A response delivered verbatim with its own content type."""

    def __init__(self, content_type: str, body: bytes):
        self.content_type = content_type
        self.body = body


class Handler(BaseHTTPRequestHandler):
    service: VariantRail

    def log_message(self, format: str, *args: Any) -> None:
        return

    def _json(self, status: int, value: Any) -> None:
        body = json.dumps(value, ensure_ascii=False, separators=(",", ":")).encode()
        self._respond(status, "application/json; charset=utf-8", body)

    def _respond(self, status: int, content_type: str, body: bytes) -> None:
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _body(self) -> Any:
        content_type = self.headers.get("Content-Type", "")
        if content_type.split(";", 1)[0].strip().lower() != "application/json":
            raise ValidationError("Content-Type must be application/json")
        try:
            length = int(self.headers.get("Content-Length", "0"))
            if length < 0 or length > 5_000_000:
                raise ValueError
            return json.loads(self.rfile.read(length))
        except (ValueError, json.JSONDecodeError) as error:
            raise ValidationError("request body must be valid JSON") from error

    def _dispatch(self) -> tuple[int, Any]:
        parts = [part for part in urlsplit(self.path).path.split("/") if part]
        if self.command == "GET" and parts == ["health"]:
            return 200, {"status": "ok"}
        if self.command == "POST" and parts == ["samples"]:
            return 201, self.service.create_sample(self._body(), self.headers.get("Idempotency-Key"))
        if len(parts) == 3 and parts[0] == "samples" and parts[2] == "runs" and self.command == "POST":
            return 201, self.service.create_run(parts[1], self._body(), self.headers.get("Idempotency-Key"))
        if len(parts) == 2 and parts[0] == "runs" and self.command == "GET":
            return 200, self.service.get_run(parts[1])
        if len(parts) == 3 and parts[0] == "runs" and parts[2] == "variants" and self.command == "GET":
            return 200, self.service.run_variants(parts[1])
        if len(parts) == 4 and parts[0] == "runs" and parts[2] == "exports" and self.command == "GET":
            content_type, body = self.service.run_export(parts[1], parts[3])
            return 200, RawBody(content_type, body)
        if len(parts) == 4 and parts[0] == "runs" and parts[2] == "compare" and self.command == "GET":
            return 200, self.service.compare_runs(parts[1], parts[3])
        if len(parts) == 4 and parts[0] == "runs" and parts[2] == "cohort" and self.command == "GET":
            return 200, self.service.cohort_runs(parts[1], parts[3])
        if len(parts) == 3 and parts[0] == "runs" and parts[2] == "cohort" and self.command == "GET":
            return 200, self.service.cohort_runs(parts[1], "")
        if len(parts) == 3 and parts[0] == "runs" and parts[2] == "provenance" and self.command == "GET":
            return 200, self.service.run_provenance(parts[1])
        raise NotFoundError("route was not found")

    def _handle(self) -> None:
        try:
            status, response = self._dispatch()
            if isinstance(response, RawBody):
                self._respond(status, response.content_type, response.body)
            else:
                self._json(status, response)
        except VariantRailError as error:
            self._json(error.status, {"error": {"code": error.code, "message": str(error)}})
        except Exception:
            self._json(500, {"error": {"code": "internal_error", "message": "internal server error"}})

    do_GET = _handle
    do_POST = _handle


def main() -> None:
    parser = argparse.ArgumentParser(description="Run the VariantRail HTTP service")
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", default=8080, type=int)
    parser.add_argument("--database", default="variantrail.db")
    arguments = parser.parse_args()
    Handler.service = VariantRail(arguments.database)
    server = ThreadingHTTPServer((arguments.host, arguments.port), Handler)
    print(f"VariantRail listening on http://{arguments.host}:{arguments.port}", flush=True)
    server.serve_forever()


if __name__ == "__main__":
    main()

from __future__ import annotations

from typing import Any, Callable

from .errors import ConflictError, NotFoundError, ValidationError
from .export import render_jsonl, render_tsv, render_vcf
from .model import identifier, run_view, sample_view
from .pipeline import execute, normalize_params
from .provenance import digest_text, verify_chain
from .store import Store
from .vcf import parse_vcf


class VariantRail:
    def __init__(self, database: str):
        self.store = Store(database)

    def _idempotent(self, key: str | None, operation: str, action: Callable[[], dict[str, Any]]) -> dict[str, Any]:
        if not key:
            raise ValidationError("Idempotency-Key header is required")
        with self.store.transaction() as connection:
            existing = connection.execute("SELECT operation, response FROM idempotency WHERE key = ?", (key,)).fetchone()
            if existing:
                if existing["operation"] != operation:
                    raise ConflictError("idempotency key was already used for another operation")
                return self.store.decode(existing["response"])
            response = action()
            connection.execute(
                "INSERT INTO idempotency(key, operation, response) VALUES (?, ?, ?)",
                (key, operation, self.store.encode(response)),
            )
            return response

    def create_sample(self, raw: Any, key: str | None) -> dict[str, Any]:
        if not isinstance(raw, dict) or set(raw) != {"id", "vcf"}:
            raise ValidationError("sample must contain exactly id and vcf")
        sample_id = identifier(raw["id"], "sample id")
        vcf_text = raw["vcf"]
        if not isinstance(vcf_text, str):
            raise ValidationError("vcf must be a string")
        parsed = parse_vcf(vcf_text)
        document = {
            "chromosomes": parsed["chromosomes"],
            "id": sample_id,
            "meta": parsed["meta"],
            "records": parsed["records"],
            "sha256": digest_text(vcf_text),
            "vcf": vcf_text,
        }

        def create() -> dict[str, Any]:
            try:
                self.store.connection.execute(
                    "INSERT INTO samples(id, document) VALUES (?, ?)",
                    (sample_id, self.store.encode(document)),
                )
            except Exception as error:
                if "UNIQUE constraint" in str(error):
                    raise ConflictError(f"sample {sample_id} already exists") from error
                raise
            return sample_view(document)

        return self._idempotent(key, f"create-sample:{sample_id}", create)

    def get_sample(self, sample_id: str) -> dict[str, Any]:
        row = self.store.connection.execute("SELECT document FROM samples WHERE id = ?", (sample_id,)).fetchone()
        if not row:
            raise NotFoundError(f"sample {sample_id} was not found")
        return self.store.decode(row["document"])

    def create_run(self, sample_id: str, raw: Any, key: str | None) -> dict[str, Any]:
        if not isinstance(raw, dict) or "id" not in raw or set(raw) - {"id", "params"}:
            raise ValidationError("run must contain exactly id and optional params")
        run_id = identifier(raw["id"], "run id")
        params = normalize_params(raw.get("params"))

        def create() -> dict[str, Any]:
            sample = self.get_sample(sample_id)
            result = execute({"records": sample["records"]}, sample["vcf"], params)
            document = {
                "id": run_id,
                "params": params,
                "provenance": result["provenance"],
                "sample_id": sample_id,
                "sample_sha256": sample["sha256"],
                "statistics": result["statistics"],
                "variants": result["variants"],
            }
            try:
                self.store.connection.execute(
                    "INSERT INTO runs(id, sample_id, document) VALUES (?, ?, ?)",
                    (run_id, sample_id, self.store.encode(document)),
                )
            except Exception as error:
                if "UNIQUE constraint" in str(error):
                    raise ConflictError(f"run {run_id} already exists") from error
                raise
            return run_view(document)

        return self._idempotent(key, f"create-run:{run_id}", create)

    def get_run(self, run_id: str) -> dict[str, Any]:
        return run_view(self._document(run_id))

    def run_variants(self, run_id: str) -> dict[str, Any]:
        variants = self._document(run_id)["variants"]
        return {"count": len(variants), "run_id": run_id, "variants": variants}

    def run_export(self, run_id: str, format: str) -> tuple[str, bytes]:
        """Render the retained variants of a saved run; the run is unchanged."""
        if format == "jsonl":
            content_type = "application/x-ndjson; charset=utf-8"
            variants = self._document(run_id)["variants"]
            body = render_jsonl(variants)
        elif format == "tsv":
            content_type = "text/tab-separated-values; charset=utf-8"
            variants = self._document(run_id)["variants"]
            body = render_tsv(variants)
        elif format == "vcf":
            content_type = "text/x-variant-call-format; charset=utf-8"
            document = self._document(run_id)
            sample = self.get_sample(document["sample_id"])
            body = render_vcf(document["variants"], sample["meta"])
        else:
            raise ValidationError("format must be one of jsonl, tsv, vcf")
        return content_type, body

    def compare_runs(self, run_id: str, other_run_id: str) -> dict[str, Any]:
        """Compare the retained ALT alleles of two finished runs; read-only."""
        left = self._document(run_id)
        right = self._document(other_run_id)
        left_alleles = _alleles(left)
        right_alleles = _alleles(right)
        shared_keys = left_alleles.keys() & right_alleles.keys()
        left_only_keys = left_alleles.keys() - right_alleles.keys()
        right_only_keys = right_alleles.keys() - left_alleles.keys()
        shared = _pick(left_alleles, shared_keys)
        left_only = _pick(left_alleles, left_only_keys)
        right_only = _pick(right_alleles, right_only_keys)
        buckets = (("shared", shared), ("left_only", left_only), ("right_only", right_only))
        return {
            "counts": {
                "left_only": len(left_only),
                "right_only": len(right_only),
                "shared": len(shared),
                "union": len(shared) + len(left_only) + len(right_only),
            },
            "gene_summary": _summary(buckets, lambda allele: allele["gene"] or "NA"),
            "impact_summary": _summary(buckets, lambda allele: allele["impact"]),
            "left": _side(run_id, left, left_alleles),
            "left_only": left_only,
            "right": _side(other_run_id, right, right_alleles),
            "right_only": right_only,
            "shared": shared,
        }

    def cohort_runs(self, run_id: str, other_run_ids: str) -> dict[str, Any]:
        """Compare the retained ALT alleles of two or more runs; read-only.

        ``other_run_ids`` is comma-joined run ids; the full path order (run_id
        first) is the cohort queue order.
        """
        run_ids = [run_id, *(part for part in other_run_ids.split(",") if part)]
        if len(run_ids) < 2:
            raise ValidationError("cohort requires at least two distinct runs")
        if len(set(run_ids)) != len(run_ids):
            raise ConflictError("cohort run ids must be distinct")
        documents = [self._document(identifier) for identifier in run_ids]
        per_run_alleles = [_alleles(document) for document in documents]

        union: dict[tuple[str, int, str, str], dict[str, Any]] = {}
        for alleles in per_run_alleles:
            for key, allele in alleles.items():
                union.setdefault(key, allele)

        runs = [
            _side(identifier, document, alleles)
            for identifier, document, alleles in zip(run_ids, documents, per_run_alleles)
        ]
        allele_entries: list[dict[str, Any]] = []
        for key in sorted(union):
            present_in = [
                identifier
                for identifier, alleles in zip(run_ids, per_run_alleles)
                if key in alleles
            ]
            allele = dict(union[key])
            allele["run_count"] = len(present_in)
            allele["present_in"] = present_in
            allele_entries.append(allele)

        run_count = len(run_ids)
        frequency = {str(number): 0 for number in range(1, run_count + 1)}
        private = {identifier: 0 for identifier in run_ids}
        gene_accumulator: dict[str, dict[str, int]] = {}
        impact_accumulator: dict[str, dict[str, int]] = {}
        core = variable = 0
        for allele in allele_entries:
            count = allele["run_count"]
            frequency[str(count)] += 1
            if count == run_count:
                core += 1
            elif count == 1:
                private[allele["present_in"][0]] += 1
            else:
                variable += 1
            for accumulator, value in (
                (gene_accumulator, allele["gene"] or "NA"),
                (impact_accumulator, allele["impact"]),
            ):
                entry = accumulator.setdefault(
                    value, {"core_alleles": 0, "unique_alleles": 0, "variable_alleles": 0}
                )
                entry["unique_alleles"] += 1
                if count == run_count:
                    entry["core_alleles"] += 1
                elif 1 < count < run_count:
                    entry["variable_alleles"] += 1

        return {
            "alleles": allele_entries,
            "counts": {
                "unique_alleles": len(allele_entries),
                "core_alleles": core,
                "variable_alleles": variable,
                "private_alleles": {identifier: private[identifier] for identifier in run_ids},
            },
            "frequency_summary": frequency,
            "gene_summary": {key: gene_accumulator[key] for key in sorted(gene_accumulator)},
            "impact_summary": {key: impact_accumulator[key] for key in sorted(impact_accumulator)},
            "run_count": run_count,
            "runs": runs,
        }

    def run_provenance(self, run_id: str) -> dict[str, Any]:
        document = self._document(run_id)
        sample = self.get_sample(document["sample_id"])
        reproduced = execute({"records": sample["records"]}, sample["vcf"], document["params"])
        chain_verified = verify_chain(document["provenance"])
        reproduction_verified = (
            [entry["output_sha256"] for entry in reproduced["provenance"]]
            == [entry["output_sha256"] for entry in document["provenance"]]
            and reproduced["statistics"] == document["statistics"]
            and reproduced["variants"] == document["variants"]
        )
        return {
            "chain_verified": chain_verified,
            "head_sha256": document["provenance"][-1]["hash"],
            "reproduction_verified": reproduction_verified,
            "run_id": run_id,
            "steps": document["provenance"],
            "verified": chain_verified and reproduction_verified,
        }

    def _document(self, run_id: str) -> dict[str, Any]:
        row = self.store.connection.execute("SELECT document FROM runs WHERE id = ?", (run_id,)).fetchone()
        if not row:
            raise NotFoundError(f"run {run_id} was not found")
        return self.store.decode(row["document"])


def _alleles(document: dict[str, Any]) -> dict[tuple[str, int, str, str], dict[str, Any]]:
    """Distinct retained ALT alleles of a run, keyed by (chrom, pos, ref, alt)."""
    alleles: dict[tuple[str, int, str, str], dict[str, Any]] = {}
    for variant in document["variants"]:
        for annotation in variant["annotations"]:
            key = (variant["chrom"], variant["pos"], variant["ref"], annotation["allele"])
            if key not in alleles:
                alleles[key] = {
                    "alt": annotation["allele"],
                    "chrom": variant["chrom"],
                    "consequence": annotation["consequence"],
                    "gene": annotation["gene"],
                    "impact": annotation["impact"],
                    "pos": variant["pos"],
                    "ref": variant["ref"],
                }
    return alleles


def _pick(alleles: dict[tuple[str, int, str, str], dict[str, Any]], keys: Any) -> list[dict[str, Any]]:
    """Alleles for the given identities, sorted by chrom, pos, ref, alt."""
    return [alleles[key] for key in sorted(keys)]


def _side(run_id: str, document: dict[str, Any], alleles: dict[Any, Any]) -> dict[str, Any]:
    return {
        "allele_count": len(alleles),
        "run_id": run_id,
        "sample_id": document["sample_id"],
        "sample_sha256": document["sample_sha256"],
    }


def _summary(buckets: Any, key_of: Callable[[dict[str, Any]], str]) -> dict[str, Any]:
    """Per-key allele counts in each comparison bucket, keys sorted."""
    counts: dict[str, dict[str, int]] = {}
    for bucket, alleles in buckets:
        for allele in alleles:
            entry = counts.setdefault(key_of(allele), {"left_only": 0, "right_only": 0, "shared": 0})
            entry[bucket] += 1
    return {key: counts[key] for key in sorted(counts)}

from __future__ import annotations

import json
import sqlite3
from contextlib import contextmanager
from pathlib import Path
from typing import Any, Iterator


class Store:
    def __init__(self, path: str):
        Path(path).parent.mkdir(parents=True, exist_ok=True)
        self.connection = sqlite3.connect(path, isolation_level=None, check_same_thread=False)
        self.connection.row_factory = sqlite3.Row
        self.connection.execute("PRAGMA foreign_keys = ON")
        self.connection.execute("PRAGMA journal_mode = WAL")
        self.connection.executescript(
            """
            CREATE TABLE IF NOT EXISTS samples (
              id TEXT PRIMARY KEY,
              document TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS runs (
              id TEXT PRIMARY KEY,
              sample_id TEXT NOT NULL REFERENCES samples(id),
              document TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS idempotency (
              key TEXT PRIMARY KEY,
              operation TEXT NOT NULL,
              response TEXT NOT NULL
            );
            """
        )

    @contextmanager
    def transaction(self) -> Iterator[sqlite3.Connection]:
        self.connection.execute("BEGIN IMMEDIATE")
        try:
            yield self.connection
        except Exception:
            self.connection.execute("ROLLBACK")
            raise
        else:
            self.connection.execute("COMMIT")

    @staticmethod
    def encode(value: Any) -> str:
        return json.dumps(value, ensure_ascii=False, separators=(",", ":"), sort_keys=True)

    @staticmethod
    def decode(value: str) -> Any:
        return json.loads(value)

from __future__ import annotations

import math
from typing import Any

from .annotate import annotate, table_sha256
from .errors import ValidationError
from .lineage import GENESIS_SHA256, json_snapshot, manifest as build_manifest, record as lineage_record
from .provenance import digest, digest_text, step
from .recordfilter import evaluate_record_filter, normalize_record_filter

PARSER_VERSION = "variantrail-vcf-1"
ALLOWED_IMPACTS = ("HIGH", "LOW", "MODERATE", "MODIFIER", "UNKNOWN")
RECORD_FILTER_REASONS = ("dp_below_min", "not_pass", "qual_below_min")
RULE_MISMATCH = "rule_mismatch"


def normalize_params(raw: Any) -> dict[str, Any]:
    """Validate run parameters and fill every documented default."""
    if raw is None:
        raw = {}
    if not isinstance(raw, dict):
        raise ValidationError("params must be an object")
    unknown = sorted(set(raw) - {"genes", "impacts", "min_dp", "min_qual", "pass_only", "record_filter"})
    if unknown:
        raise ValidationError(f"params contains unknown fields: {', '.join(unknown)}")

    params: dict[str, Any] = {"genes": [], "impacts": [], "min_dp": 0, "min_qual": 0.0, "pass_only": False}
    if "min_qual" in raw:
        value = raw["min_qual"]
        if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value) or value < 0:
            raise ValidationError("params.min_qual must be a non-negative finite number")
        params["min_qual"] = float(value)
    if "min_dp" in raw:
        value = raw["min_dp"]
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise ValidationError("params.min_dp must be a non-negative integer")
        params["min_dp"] = value
    if "pass_only" in raw:
        if not isinstance(raw["pass_only"], bool):
            raise ValidationError("params.pass_only must be a boolean")
        params["pass_only"] = raw["pass_only"]
    for key in ("genes", "impacts"):
        if key not in raw:
            continue
        value = raw[key]
        if not isinstance(value, list) or any(not isinstance(item, str) or not item for item in value):
            raise ValidationError(f"params.{key} must be an array of non-empty strings")
        if len(set(value)) != len(value):
            raise ValidationError(f"params.{key} must not contain duplicate values")
        params[key] = sorted(value)
    for impact in params["impacts"]:
        if impact not in ALLOWED_IMPACTS:
            raise ValidationError(f"params.impacts entry {impact} is not one of {', '.join(ALLOWED_IMPACTS)}")
    if "record_filter" in raw:
        params["record_filter"] = normalize_record_filter(raw["record_filter"])
    return params


def execute(parsed: dict[str, Any], vcf_text: str, params: dict[str, Any], lineage: bool = False) -> dict[str, Any]:
    """Run ingest -> filter -> annotate -> summarize and record each link.

    With ``lineage=True`` the result additionally carries a self-contained
    ``lineage`` manifest (see :mod:`variantrail.lineage`). A non-boolean
    ``lineage`` raises ``TypeError``; so do parameters whose values cannot be
    represented as JSON, and that check runs before any pipeline step.
    """
    if not isinstance(lineage, bool):
        raise TypeError("lineage must be a boolean")
    if lineage:
        # Validated and isolated before any step executes; later mutation of
        # the caller's params can never reach the returned manifest.
        params_snapshot = json_snapshot(params)
    else:
        params_snapshot = None
    steps: list[dict[str, Any]] = []
    lineage_steps: list[dict[str, Any]] = []

    def link(
        name: str,
        step_params: dict[str, Any],
        input_sha256: str,
        output_sha256: str,
    ) -> None:
        """Append one provenance link and, when enabled, its lineage record."""
        steps.append(
            step(
                len(steps) + 1,
                name,
                step_params,
                input_sha256,
                output_sha256,
                None if not steps else steps[-1]["hash"],
            )
        )
        if lineage:
            previous_sha256 = GENESIS_SHA256 if not lineage_steps else lineage_steps[-1]["sha256"]
            lineage_steps.append(
                lineage_record(
                    name,
                    json_snapshot(step_params),
                    input_sha256,
                    output_sha256,
                    previous_sha256,
                )
            )

    records = parsed["records"]
    link(
        "ingest",
        {"parser_version": PARSER_VERSION},
        digest_text(vcf_text),
        digest({"records": records}),
    )

    reasons = list(RECORD_FILTER_REASONS)
    expression = params.get("record_filter")
    if expression is not None:
        reasons.append(RULE_MISMATCH)
    counts = dict.fromkeys(reasons, 0)
    kept: list[dict[str, Any]] = []
    for record in records:
        reason = record_reason(record, params)
        if reason is None:
            kept.append(record)
        else:
            counts[reason] += 1
    filter_params: dict[str, Any] = {
        "min_dp": params["min_dp"],
        "min_qual": params["min_qual"],
        "pass_only": params["pass_only"],
    }
    if expression is not None:
        filter_params["record_filter"] = expression
    link(
        "filter",
        filter_params,
        steps[-1]["output_sha256"],
        digest({"filter_counts": counts, "records": kept}),
    )

    variants: list[dict[str, Any]] = []
    filtered = 0
    for record in kept:
        annotations = [entry for entry in annotate(record) if allele_selected(entry, params)]
        if not annotations:
            filtered += 1
            continue
        variants.append(variant_document(record, annotations))
    counts = {**counts, "allele_filtered": filtered}
    link(
        "annotate",
        {
            "annotation_table_sha256": table_sha256(),
            "genes": params["genes"],
            "impacts": params["impacts"],
        },
        steps[-1]["output_sha256"],
        digest({"filter_counts": counts, "variants": variants}),
    )

    statistics = summarize(records, variants, counts)
    link("summarize", {}, steps[-1]["output_sha256"], digest(statistics))

    result: dict[str, Any] = {
        "filter_counts": counts,
        "provenance": steps,
        "statistics": statistics,
        "variants": variants,
    }
    if lineage:
        result["lineage"] = build_manifest(vcf_text, params_snapshot, lineage_steps)
    return result


def record_reason(record: dict[str, Any], params: dict[str, Any]) -> str | None:
    """First failing record-level filter, in the documented precedence order."""
    if params["pass_only"] and record["filter"] != ["PASS"]:
        return "not_pass"
    if record["qual"] is None:
        if params["min_qual"] > 0:
            return "qual_below_min"
    elif record["qual"] < params["min_qual"]:
        return "qual_below_min"
    if record["dp"] is None:
        if params["min_dp"] > 0:
            return "dp_below_min"
    elif record["dp"] < params["min_dp"]:
        return "dp_below_min"
    expression = params.get("record_filter")
    if expression is not None and not evaluate_record_filter(expression, record):
        return RULE_MISMATCH
    return None


def allele_selected(annotation: dict[str, Any], params: dict[str, Any]) -> bool:
    """Allele-level allowlists, applied after annotation."""
    if params["genes"] and annotation["gene"] not in params["genes"]:
        return False
    if params["impacts"] and annotation["impact"] not in params["impacts"]:
        return False
    return True


def variant_document(record: dict[str, Any], annotations: list[dict[str, Any]]) -> dict[str, Any]:
    return {
        "alts": list(record["alts"]),
        "annotations": annotations,
        "chrom": record["chrom"],
        "dp": record["dp"],
        "filter": list(record["filter"]),
        "id": record["id"],
        "info": dict(record["info"]),
        "line": record["line"],
        "pos": record["pos"],
        "qual": record["qual"],
        "raw": record["raw"],
        "ref": record["ref"],
    }


def summarize(
    records: list[dict[str, Any]],
    variants: list[dict[str, Any]],
    counts: dict[str, int],
) -> dict[str, Any]:
    consequence_counts: dict[str, int] = {}
    gene_counts: dict[str, int] = {}
    impact_counts: dict[str, int] = {}
    alleles_kept = 0
    for variant in variants:
        for annotation in variant["annotations"]:
            alleles_kept += 1
            _bump(consequence_counts, annotation["consequence"])
            _bump(gene_counts, annotation["gene"] or "NA")
            _bump(impact_counts, annotation["impact"])
    return {
        "alleles_kept": alleles_kept,
        "alleles_total": sum(len(record["alts"]) for record in records),
        "consequence_counts": _ordered(consequence_counts),
        "filter_counts": _ordered(counts),
        "gene_counts": _ordered(gene_counts),
        "impact_counts": _ordered(impact_counts),
        "records_filtered": len(records) - len(variants),
        "records_kept": len(variants),
        "records_total": len(records),
    }


def _bump(counts: dict[str, int], key: str) -> None:
    counts[key] = counts.get(key, 0) + 1


def _ordered(counts: dict[str, int]) -> dict[str, int]:
    return {key: counts[key] for key in sorted(counts)}

"""Structured record-level filter expressions.

A node is either a logical expression (``all`` / ``any`` / ``not``) or a
condition object ``{"field", "op", "value"}``. Conditions are evaluated
against parsed VCF records; missing, null or unparseable values make every
non-``exists`` condition false, so ``not`` expresses "missing" tests.
"""

from __future__ import annotations

import math
import re
from typing import Any

from .errors import ValidationError

LOGICAL_OPS = ("all", "any", "not")
CONDITION_OPS = ("eq", "exists", "gt", "gte", "in", "lt", "lte")
ORDERED_OPS = ("gt", "gte", "lt", "lte")
MAX_DEPTH = 16

_SCALAR_FIELDS = {"chrom": "string", "id": "string", "ref": "string"}
_NUMBER_FIELDS = {"dp": "number", "pos": "number", "qual": "number"}
_LIST_FIELDS = {"alt": "list", "filter": "list"}
_DECIMAL = re.compile(r"[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$")


def normalize_record_filter(raw: Any) -> dict[str, Any]:
    """Validate and canonicalize a record_filter expression.

    Logical arrays keep their order (``all``/``any`` semantics may rely on it
    only for short-circuiting, never for the result); ``in`` arrays are sorted
    because membership is order-independent, and numeric values become floats
    like the other numeric params.
    """
    if not isinstance(raw, dict):
        raise ValidationError("params.record_filter must be an expression object")
    return _normalize_node(raw, 0)


def _normalize_node(node: Any, depth: int) -> dict[str, Any]:
    if not isinstance(node, dict):
        raise ValidationError("record_filter: every node must be an object")
    keys = set(node)
    logical = keys.intersection(LOGICAL_OPS)
    is_condition = "field" in keys or "op" in keys
    if logical and is_condition:
        raise ValidationError("record_filter: a node must not mix all/any/not with a condition")
    if len(logical) > 1:
        raise ValidationError("record_filter: a node must use exactly one of all, any, not")
    if logical:
        (name,) = logical
        if keys != {name}:
            raise ValidationError(f"record_filter: {name} node has unknown keys")
        if depth >= MAX_DEPTH:
            raise ValidationError("record_filter: nesting must not exceed 16 levels")
        child = node[name]
        if name in ("all", "any"):
            if not isinstance(child, list) or not child:
                raise ValidationError(f"record_filter: {name} must be a non-empty array")
            return {name: [_normalize_node(part, depth + 1) for part in child]}
        if not isinstance(child, dict):
            raise ValidationError("record_filter: not must wrap a single expression node")
        return {"not": _normalize_node(child, depth + 1)}
    if not is_condition:
        raise ValidationError(
            "record_filter: every node must be one of all, any, not or a condition object"
        )
    return _normalize_condition(node, keys)


def _normalize_condition(node: dict[str, Any], keys: set[str]) -> dict[str, Any]:
    if "field" not in node or "op" not in node:
        raise ValidationError("record_filter: condition must contain field and op")
    unknown = keys - {"field", "op", "value"}
    if unknown:
        raise ValidationError(f"record_filter: condition has unknown keys: {', '.join(sorted(unknown))}")
    field = node["field"]
    op = node["op"]
    if not isinstance(field, str) or not field:
        raise ValidationError("record_filter: field must be a non-empty string")
    if not isinstance(op, str) or not op:
        raise ValidationError("record_filter: op must be a non-empty string")
    kind = _field_kind(field)
    if kind is None:
        raise ValidationError(f"record_filter: unknown field {field}")
    if op not in CONDITION_OPS:
        raise ValidationError(f"record_filter: unknown op {op}")
    if op == "exists":
        if "value" in node:
            raise ValidationError("record_filter: op exists does not take a value")
        return {"field": field, "op": "exists"}
    if "value" not in node:
        raise ValidationError(f"record_filter: op {op} requires a value")
    value = node["value"]

    if op in ORDERED_OPS:
        if kind not in ("number", "info"):
            raise ValidationError(
                f"record_filter: op {op} only applies to pos, qual, dp or info.<KEY>"
            )
        return {"field": field, "op": op, "value": _number(value, field, op)}

    if op == "eq":
        if kind == "number":
            return {"field": field, "op": "eq", "value": _number(value, field, op)}
        if kind == "list":
            return {"field": field, "op": "eq", "value": _string(value, field, op)}
        # string fields and INFO values are compared verbatim as strings.
        return {"field": field, "op": "eq", "value": _string(value, field, op)}

    # op == "in"
    if not isinstance(value, list) or not value:
        raise ValidationError(f"record_filter: {field} in requires a non-empty array")
    if kind == "number":
        members = [_number(item, field, "in") for item in value]
    else:
        members = [_string(item, field, "in") for item in value]
    return {"field": field, "op": "in", "value": sorted(members)}


def _field_kind(field: str) -> str | None:
    if field in _SCALAR_FIELDS:
        return "string"
    if field in _NUMBER_FIELDS:
        return "number"
    if field in _LIST_FIELDS:
        return "list"
    if field.startswith("info.") and len(field) > len("info."):
        return "info"
    return None


def _number(value: Any, field: str, op: str) -> float:
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
        raise ValidationError(f"record_filter: {field} {op} requires a finite number value")
    return float(value)


def _string(value: Any, field: str, op: str) -> str:
    if not isinstance(value, str) or not value:
        raise ValidationError(f"record_filter: {field} {op} requires a non-empty string value")
    return value


def evaluate_record_filter(expression: dict[str, Any], record: dict[str, Any]) -> bool:
    """Evaluate a normalized expression against one parsed VCF record."""
    if "all" in expression:
        return all(evaluate_record_filter(part, record) for part in expression["all"])
    if "any" in expression:
        return any(evaluate_record_filter(part, record) for part in expression["any"])
    if "not" in expression:
        return not evaluate_record_filter(expression["not"], record)
    return _evaluate_condition(expression, record)


def _evaluate_condition(condition: dict[str, Any], record: dict[str, Any]) -> bool:
    field = condition["field"]
    op = condition["op"]
    present, value = _resolve(field, record)
    if op == "exists":
        # INFO bare flags are stored as null but count as present.
        return present if field.startswith("info.") else present and value is not None
    if not present or value is None:
        return False

    if field.startswith("info."):
        if op == "in":
            return value in condition["value"]
        if op == "eq":
            return value == condition["value"]
        number = _decimal(value)
        if number is None:
            return False
        return _compare(number, op, condition["value"])

    if isinstance(value, list):
        # alt and filter: any element matching satisfies eq and in.
        if op == "eq":
            return condition["value"] in value
        return any(item in condition["value"] for item in value)

    if op == "eq":
        return value == condition["value"]
    if op == "in":
        return value in condition["value"]
    return _compare(value, op, condition["value"])


def _resolve(field: str, record: dict[str, Any]) -> tuple[bool, Any]:
    if field.startswith("info."):
        key = field[len("info."):]
        info = record["info"]
        return key in info, info.get(key)
    if field == "alt":
        value = record["alts"]
    else:
        value = record[field]
    return value is not None, value


def _decimal(text: str | None) -> float | None:
    """Fully parse a finite decimal number; bare flags and junk return None."""
    if text is None or not _DECIMAL.match(text):
        return None
    number = float(text)
    return number if math.isfinite(number) else None


def _compare(actual: float, op: str, expected: float) -> bool:
    if op == "lt":
        return actual < expected
    if op == "lte":
        return actual <= expected
    if op == "gt":
        return actual > expected
    return actual >= expected

from __future__ import annotations

import re
from typing import Any

from .errors import ValidationError

_FILEFORMAT = re.compile(r"VCFv4\.[0-9]+$")
_META_KEY = re.compile(r"[A-Za-z][A-Za-z0-9_.-]*$")
_CHROM = re.compile(r"[A-Za-z0-9_.]+$")
_SEQUENCE = re.compile(r"[ACGTN]+$")
_QUAL = re.compile(r"[0-9]+(?:\.[0-9]+)?$")
_FILTER_TOKEN = re.compile(r"[A-Za-z0-9_.]+$")
_INFO_KEY = re.compile(r"[A-Za-z_][A-Za-z0-9_.]*$")
_HEADER = ("#CHROM", "POS", "ID", "REF", "ALT", "QUAL", "FILTER", "INFO")


def parse_vcf(text: Any) -> dict[str, Any]:
    """Parse the supported VCF subset.

    Every structural or field-level violation raises ``ValidationError`` whose
    message names the offending line. Record order is preserved; ``raw`` keeps
    the original line so anything in the output stays traceable.
    """
    if not isinstance(text, str):
        raise ValidationError("vcf must be a string")
    lines = text.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    if not any(line.strip() for line in lines):
        raise ValidationError("vcf must not be empty")

    meta: list[dict[str, str]] = []
    records: list[dict[str, Any]] = []
    chromosomes: list[str] = []
    seen_chromosomes: set[str] = set()
    seen_variants: dict[tuple[Any, ...], int] = {}
    header_line: int | None = None
    current_chromosome: str | None = None
    last_position = 0

    for number, source in enumerate(lines, start=1):
        line = source[:-1] if source.endswith("\r") else source
        if not line.strip():
            raise ValidationError(f"line {number}: blank lines are not allowed")

        if header_line is None:
            if line.startswith("##"):
                entry = _meta_entry(line, number)
                if not meta and entry["key"] != "fileformat":
                    raise ValidationError(f"line {number}: the first line must be a ##fileformat meta line")
                if entry["key"] == "fileformat" and not _FILEFORMAT.match(entry["value"]):
                    raise ValidationError(f"line {number}: fileformat must be VCFv4.x")
                meta.append(entry)
                continue
            if line.startswith("#"):
                if tuple(line.split("\t")) != _HEADER:
                    raise ValidationError(
                        f"line {number}: the #CHROM header must be exactly "
                        "#CHROM POS ID REF ALT QUAL FILTER INFO separated by tabs"
                    )
                header_line = number
                continue
            raise ValidationError(f"line {number}: data record appears before the #CHROM header line")

        if line.startswith("#"):
            raise ValidationError(f"line {number}: header lines are not allowed after the #CHROM header")

        record = _record(line, number)
        chromosome = record["chrom"]
        if chromosome != current_chromosome:
            if chromosome in seen_chromosomes:
                raise ValidationError(f"line {number}: chromosome {chromosome} appears in more than one block")
            seen_chromosomes.add(chromosome)
            chromosomes.append(chromosome)
            current_chromosome = chromosome
            last_position = 0
        if record["pos"] < last_position:
            raise ValidationError(f"line {number}: records must be sorted by POS within {chromosome}")
        last_position = record["pos"]

        key = (chromosome, record["pos"], record["ref"], tuple(record["alts"]))
        if key in seen_variants:
            raise ValidationError(
                f"line {number}: duplicate variant {chromosome}:{record['pos']} "
                f"{record['ref']}>{','.join(record['alts'])} first appeared at line {seen_variants[key]}"
            )
        seen_variants[key] = number
        records.append(record)

    if header_line is None:
        raise ValidationError("vcf has no #CHROM header line")
    if not records:
        raise ValidationError("vcf has no data records after the #CHROM header")
    return {"chromosomes": chromosomes, "meta": meta, "records": records}


def _meta_entry(line: str, number: int) -> dict[str, str]:
    key, separator, value = line[2:].partition("=")
    if not separator or not _META_KEY.match(key) or not value:
        raise ValidationError(f"line {number}: meta lines must look like ##key=value")
    return {"key": key, "raw": line, "value": value}


def _record(line: str, number: int) -> dict[str, Any]:
    fields = line.split("\t")
    if len(fields) != 8:
        raise ValidationError(f"line {number}: expected 8 tab-separated fields, found {len(fields)}")
    chrom, pos_text, id_text, ref_text, alt_text, qual_text, filter_text, info_text = fields

    if not _CHROM.match(chrom):
        raise ValidationError(f"line {number}: CHROM must be a non-empty chromosome name")
    if not pos_text.isdigit() or int(pos_text) < 1:
        raise ValidationError(f"line {number}: POS must be a positive integer")
    position = int(pos_text)

    identifier = None if id_text == "." else id_text
    if identifier is not None and (not identifier or any(character in identifier for character in " \t;,")):
        raise ValidationError(f"line {number}: ID must be '.' or a value without whitespace, ';' or ','")

    reference = ref_text.upper()
    if not _SEQUENCE.match(reference):
        raise ValidationError(f"line {number}: REF must be a non-empty sequence of A, C, G, T or N")

    alternates = [allele.upper() for allele in alt_text.split(",")]
    if any(not _SEQUENCE.match(allele) for allele in alternates):
        raise ValidationError(f"line {number}: ALT must be a comma-separated list of A, C, G, T or N sequences")
    if len(set(alternates)) != len(alternates):
        raise ValidationError(f"line {number}: ALT must not repeat an allele")

    if qual_text == ".":
        quality: float | None = None
    elif _QUAL.match(qual_text):
        quality = float(qual_text)
    else:
        raise ValidationError(f"line {number}: QUAL must be '.' or a non-negative number")

    if filter_text == ".":
        filters: list[str] = []
    else:
        filters = filter_text.split(";")
        if any(not _FILTER_TOKEN.match(token) for token in filters):
            raise ValidationError(f"line {number}: FILTER must be '.', 'PASS' or ';'-separated tokens")
        if len(set(filters)) != len(filters):
            raise ValidationError(f"line {number}: FILTER must not repeat a token")
        if "PASS" in filters and len(filters) > 1:
            raise ValidationError(f"line {number}: FILTER 'PASS' must not be combined with other tokens")

    info: dict[str, str | None] = {}
    if info_text != ".":
        for entry in info_text.split(";"):
            key, separator, value = entry.partition("=")
            if not _INFO_KEY.match(key):
                raise ValidationError(f"line {number}: INFO entry {entry!r} does not start with a valid key")
            if key in info:
                raise ValidationError(f"line {number}: INFO key {key} is repeated")
            if not separator:
                info[key] = None
            elif not value or any(character.isspace() for character in value):
                raise ValidationError(f"line {number}: INFO {key} must have a non-empty value without whitespace")
            else:
                info[key] = value

    if "DP" not in info:
        depth: int | None = None
    elif info["DP"] is None or not info["DP"].isdigit():
        raise ValidationError(f"line {number}: INFO/DP must be a non-negative integer")
    else:
        depth = int(info["DP"])

    return {
        "alts": alternates,
        "chrom": chrom,
        "dp": depth,
        "filter": filters,
        "id": identifier,
        "info": info,
        "line": number,
        "pos": position,
        "qual": quality,
        "raw": line,
        "ref": reference,
    }

